const ALLOWED = {
  facial_affect: ["flat", "blunted", "guarded", "suspicious", "fearful", "tense", "distant", "perplexed", "softened"],
  body_behavior: ["still", "arms_crossed", "hands_fidget", "head_tilt_listening", "glance_at_vent", "shrink_back"],
  trust: ["very_low", "low", "moderate", "high", "very_high"]
};

// The agent returns an object when "Require Specific Output Format" is on, a string otherwise.
let out = $('Theodore Miller').first().json.output;
if (typeof out === 'string') {
  const cleaned = out.replace(/```json|```/g, '').trim();
  try { out = JSON.parse(cleaned); } catch (e) { out = { spoken_response: cleaned }; }
}
out = out || {};

const nv = out.nonverbal_behavior || {};
const cs = out.clinical_state || {};
const pick = (v, list, fallback) => (list.includes(v) ? v : fallback);
const num = (v, min, max, fallback) => (typeof v === 'number' && !isNaN(v) ? Math.min(max, Math.max(min, v)) : fallback);

const audio = $input.first().binary?.data;

return [{
  json: {
    spoken_response: out.spoken_response || "",
    nonverbal_behavior: {
      eye_contact_ratio: num(nv.eye_contact_ratio, 0, 1, 0.1),
      facial_affect: pick(nv.facial_affect, ALLOWED.facial_affect, "flat"),
      body_behavior: pick(nv.body_behavior, ALLOWED.body_behavior, "still"),
      response_latency_ms: Math.round(num(nv.response_latency_ms, 0, 15000, 4000))
    },
    clinical_state: {
      current_trust_level: pick(cs.current_trust_level, ALLOWED.trust, "very_low"),
      applied_disorganization_level: Math.round(num(cs.applied_disorganization_level, 1, 5, 1)),
      disclosed_topics: Array.isArray(cs.disclosed_topics) ? cs.disclosed_topics : []
    },
    audio_base64: audio ? audio.data : null,
    audio_mime_type: audio ? audio.mimeType : null
  }
}];
